local minimized = false
local fullSize = UDim2.fromOffset(420, 360)
local miniSize = UDim2.fromOffset(420, 50)
minBtn.MouseButton1Click:Connect(function()
    minimized = not minimized
    card.Size = minimized and miniSize or fullSize
    minBtn.Text = minimized and "+" or "–"
end)

discordLink.MouseButton1Click:Connect(function()
    local ok = pcall(function() setclipboard(DISCORD_LINK) end)
    if ok then
        discordLink.TextColor3 = Color3.fromRGB(80, 220, 120)
        discordLink.Text = "Copied! " .. DISCORD_LINK
        task.delay(2, function()
            if discordLink and discordLink.Parent then
                discordLink.TextColor3 = Color3.fromRGB(120, 170, 255)
                discordLink.Text = DISCORD_LINK
            end
        end)
    end
end)

getKey.MouseButton1Click:Connect(function()
    local ok = pcall(function() setclipboard(DISCORD_LINK) end)
    if ok then
        status.TextColor3 = Color3.fromRGB(80, 220, 120)
        status.Text = "Discord link copied! Join for the key."
    else
        status.TextColor3 = Color3.fromRGB(255, 200, 80)
        status.Text = "Copy manually: " .. DISCORD_LINK
    end
end)

local unlocked = false
local function tryUnlock()
    if unlocked then return end
    local entered = (input.Text or ""):gsub("%s+", "")
    if entered == VALID_KEY then
        unlocked = true
        status.TextColor3 = Color3.fromRGB(80, 220, 120)
        status.Text = "Key correct! Loading hub..."
        submit.Text = "Loading..."
        submit.BackgroundColor3 = Color3.fromRGB(40, 160, 80)
        task.wait(0.5)
        pcall(function() gui:Destroy() end)
        local ok, err = pcall(function()
            loadstring(OBF_CODE)()
        end)
        if not ok then
            warn("[Rivo] Failed to load obfuscated script:", err)
        end
    else
        status.TextColor3 = Color3.fromRGB(255, 90, 90)
        status.Text = "Invalid key."
    end
end

submit.MouseButton1Click:Connect(tryUnlock)
input.FocusLost:Connect(function(enterPressed)
    if enterPressed then tryUnlock() end
end)
